import React from 'react';
import '../styles/routedetails.css';

function RouteDetails({ routeData }) {
    if (!routeData) {
        return null;
    }

    const CalculateDistance  =  (lat1, lng1, lat2, lng2) => {
        const dLat  =  lat2  -  lat1;
        const dLng  =  lng2  -  lng1;
        const dist  =  Math.sqrt(dLat  *  dLat  +  dLng  *  dLng)  *  111;
        return Math.round(dist);
    };

    const GetTimeFromDistance  =  (km) => {
        const hours  =  Math.floor(km  /  80);
        const minutes  =  Math.round((km  %  80)  /  80  *  60);
        return { hours:  hours, minutes:  minutes };
    };

    const startLat  =  39.9042;
    const startLng  =  116.4074;
    const endLat  =  39.8686;
    const endLng  =  116.5516;

    const waypoints  =  routeData.waypoints || [];
    const BuildPoints  =  () => {
        const result  =  [];
        result.push({ name:  routeData.departure, lat:  startLat, lng:  startLng, type:  'start' });

        waypoints.forEach((wp, idx) => {
            const offset  =  0.02;
            const ratio  =  (idx  +  1)  /  (waypoints.length  +  1);
            const wpLat  =  startLat  +  (endLat  -  startLat)  *  ratio;
            const wpLng  =  startLng  +  (endLng  -  startLng)  *  ratio  +  offset  *  (idx  %  2  ===  0  ?  1  :  -1);
            result.push({ name:  wp.name, lat:  wpLat, lng:  wpLng, type:  'waypoint' });
        });

        result.push({ name:  routeData.destination, lat:  endLat, lng:  endLng, type:  'end' });
        return result;
    };

    const points  =  BuildPoints();
    const BuildSegments  =  () => {
        const result  =  [];
        for (let i  =  0; i  <  points.length  -  1; i  +=  1) {
            const curr  =  points[i];
            const next  =  points[i  +  1];
            const dist  =  CalculateDistance(curr.lat, curr.lng, next.lat, next.lng);
            const time  =  GetTimeFromDistance(dist);
            result.push({
                from:  curr.name,
                to:  next.name,
                distance:  dist,
                time:  time
            });
        }
        return result;
    };

    const segments  =  BuildSegments();
    const totalDistance  =  segments.reduce((sum, seg)  =>  sum  +  seg.distance, 0);
    const totalMinutes  =  segments.reduce((sum, seg)  =>  sum  +  seg.time.hours  *  60  +  seg.time.minutes, 0);
    const totalHours  =  Math.floor(totalMinutes  /  60);
    const remainMinutes  =  totalMinutes  %  60;

    return (
        <div className  =  "route-details">
            <h3>行程详情</h3>
            <div className  =  "summary">
                <div className  =  "summary-item">
                    <span className  =  "label">总距离</span>
                    <span className  =  "value">{totalDistance}公里</span>
                </div>
                <div className  =  "summary-item">
                    <span className  =  "label">预计时长</span>
                    <span className  =  "value">{totalHours}小时{remainMinutes}分钟</span>
                </div>
            </div>
            <div className  =  "timeline">
                {segments.map((seg, idx)  =>  (
                    <div key  =  {idx} className  =  "timeline-item">
                        <div className  =  "timeline-point"></div>
                        <div className  =  "timeline-content">
                            <div className  =  "segment-info">
                                <span className  =  "from">{seg.from}</span>
                                <span className  =  "arrow">→</span>
                                <span className  =  "to">{seg.to}</span>
                            </div>
                            <div className  =  "segment-stats">
                                <span className  =  "distance">{seg.distance}公里</span>
                                <span className  =  "divider">|</span>
                                <span className  =  "time">{seg.time.hours  >  0  ?  seg.time.hours  +  '小时'  :  ''}{seg.time.minutes}分钟</span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}

export default RouteDetails;

